import "server-only";
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { randomBytes } from "node:crypto";
import sharp from "sharp";

// Uploaded media lives outside /public and is served by /media/[...path] so it works after `next build`.
// Swap this module for an S3/R2/Cloudinary implementation in multi-server deployments.
export const UPLOAD_ROOT = path.resolve(/*turbopackIgnore: true*/ process.env.UPLOAD_DIR || path.join(process.cwd(), "uploads"));

const MAX_IMAGE_BYTES = 8 * 1024 * 1024;
const MAX_VIDEO_BYTES = 60 * 1024 * 1024;

function sniff(buf: Buffer): "image" | "mp4" | "webm" | null {
  const hex = buf.subarray(0, 12).toString("hex");
  if (hex.startsWith("ffd8ff")) return "image"; // jpeg
  if (hex.startsWith("89504e47")) return "image"; // png
  if (hex.startsWith("47494638")) return "image"; // gif
  if (hex.startsWith("52494646") && buf.subarray(8, 12).toString() === "WEBP") return "image";
  if (buf.subarray(4, 8).toString() === "ftyp") {
    const brand = buf.subarray(8, 12).toString();
    if (/^(avif|avis|heic|heix|mif1)/.test(brand)) return "image";
    return "mp4";
  }
  if (hex.startsWith("1a45dfa3")) return "webm";
  return null;
}

export type StoredFile = { url: string; kind: "IMAGE" | "VIDEO" };

/**
 * Validates by magic bytes (not the client-supplied MIME type), re-encodes images with sharp
 * (strips EXIF/GPS metadata and neutralises polyglot files) and stores under a random name.
 */
export async function storeUpload(file: File, folder: "products" | "gallery" | "banners" | "categories"): Promise<StoredFile> {
  if (!file || file.size === 0) throw new Error("Empty file");
  const buf = Buffer.from(await file.arrayBuffer());
  const kind = sniff(buf);
  if (!kind) throw new Error(`Unsupported file type: ${file.name}`);

  const dir = path.join(/*turbopackIgnore: true*/ UPLOAD_ROOT, folder);
  await mkdir(dir, { recursive: true });
  const id = randomBytes(12).toString("hex");

  if (kind === "image") {
    if (buf.length > MAX_IMAGE_BYTES) throw new Error("Images must be under 8 MB");
    const name = `${id}.webp`;
    await sharp(buf, { limitInputPixels: 40_000_000 })
      .rotate()
      .resize({ width: 1600, height: 1600, fit: "inside", withoutEnlargement: true })
      .webp({ quality: 82 })
      .toFile(path.join(dir, name));
    return { url: `/media/${folder}/${name}`, kind: "IMAGE" };
  }

  if (buf.length > MAX_VIDEO_BYTES) throw new Error("Videos must be under 60 MB");
  const name = `${id}.${kind}`;
  await writeFile(path.join(dir, name), buf);
  return { url: `/media/${folder}/${name}`, kind: "VIDEO" };
}
